    result = {}
    tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    if chan_est!=None :
       ##### This lane is PAM4. Set the TX if the TX source for this lane is Credo TX
        if line_encoding_mode=='pam4' and gPam4TxSourceIsCredo==1:
            if   chan_est <0.90:  taps=[+2, -8,17,0,0] # default or used for channel analyzer
