def log_to_phy_lane_mapping_table(hw_system='QSFP'):
    sel_tile(0) 
    
    #### Default setup #### No Logical-to-Physical Mapping, All Polarities set to Default
    if 'OFF' in hw_system.upper():
        for tile in range(4):
            sel_tile(tile)            
            for group in range(8):
                set_log_to_phy_lane_mapping(group=group, tx_val=range(8), rx_val=range(8))

    #### QSFP EVB Setup #### No Logical-to-Physical Mapping for QSFP EVB with loopback Modules 
    elif 'QSFP' in hw_system.upper():
        for group in range(8):
            set_log_to_phy_lane_mapping(group=group, tx_val=range(8), rx_val=range(8))
    #### SMK EVB Setup #### No Logical-to-Physical Mapping for SMK EVB each lane in self-loopback mode
    elif 'SMK' in hw_system.upper() or 'SMA' in hw_system.upper():
        for group in range(8):
            set_log_to_phy_lane_mapping(group=group, tx_val=range(8), rx_val=range(8))
    #### CoWoS Logical-to-Physical Mapping set for Toshi's front-port connections (2019-05-20)
    else:
        for tile in range(4):
            sel_tile(tile)            
            if tile==0:
                set_log_to_phy_lane_mapping(0, [5, 3, 6, 1, 7, 4, 0, 2], [3, 0, 7, 5, 4, 2, 1, 6])
                set_log_to_phy_lane_mapping(1, [5, 6, 3, 2, 1, 7, 0, 4], [7, 1, 3, 4, 2, 0, 5, 6])
                set_log_to_phy_lane_mapping(2, [5, 4, 0, 3, 2, 6, 1, 7], [4, 0, 5, 2, 6, 3, 7, 1])
                set_log_to_phy_lane_mapping(3, [1, 6, 3, 4, 2, 7, 5, 0], [6, 0, 7, 1, 2, 3, 5, 4])
                set_log_to_phy_lane_mapping(4, [7, 2, 5, 0, 1, 4, 3, 6], [1, 2, 4, 3, 6, 5, 0, 7])
                set_log_to_phy_lane_mapping(5, [5, 2, 3, 6, 4, 0, 1, 7], [6, 2, 3, 1, 4, 7, 0, 5])
                set_log_to_phy_lane_mapping(6, [3, 4, 5, 2, 1, 0, 7, 6], [4, 1, 6, 3, 2, 0, 7, 5])
                set_log_to_phy_lane_mapping(7, [7, 2, 1, 6, 0, 5, 3, 4], [6, 0, 7, 1, 4, 2, 5, 3])
            elif tile==1:
                set_log_to_phy_lane_mapping(0, [0, 1, 5, 4, 2, 3, 6, 7], [6, 0, 7, 1, 2, 4, 5, 3])
                set_log_to_phy_lane_mapping(1, [1, 7, 2, 0, 4, 6, 3, 5], [7, 2, 6, 0, 4, 5, 3, 1])
                set_log_to_phy_lane_mapping(2, [6, 4, 1, 7, 2, 0, 5, 3], [7, 0, 5, 1, 6, 4, 3, 2])
                set_log_to_phy_lane_mapping(3, [7, 5, 2, 1, 4, 0, 3, 6], [7, 0, 4, 1, 6, 2, 5, 3])
                set_log_to_phy_lane_mapping(4, [2, 6, 0, 5, 4, 7, 1, 3], [4, 0, 6, 1, 7, 3, 5, 2])
                set_log_to_phy_lane_mapping(5, [4, 7, 2, 3, 1, 5, 0, 6], [6, 1, 7, 2, 4, 0, 5, 3])
                set_log_to_phy_lane_mapping(6, [0, 5, 7, 4, 1, 2, 6, 3], [7, 2, 6, 1, 4, 5, 3, 0])
                set_log_to_phy_lane_mapping(7, [1, 3, 5, 6, 7, 2, 0, 4], [0, 4, 7, 1, 5, 6, 3, 2])
            elif tile==2:
                set_log_to_phy_lane_mapping(0, [5, 7, 4, 2, 3, 1, 6, 0], [1, 5, 0, 4, 3, 7, 2, 6])
                set_log_to_phy_lane_mapping(1, [5, 4, 1, 0, 3, 7, 2, 6], [3, 4, 0, 6, 1, 5, 2, 7])
                set_log_to_phy_lane_mapping(2, [3, 4, 6, 0, 5, 7, 1, 2], [4, 1, 6, 2, 7, 3, 5, 0])
                set_log_to_phy_lane_mapping(3, [7, 3, 6, 1, 2, 5, 4, 0], [5, 6, 0, 4, 1, 7, 3, 2])
                set_log_to_phy_lane_mapping(4, [2, 1, 0, 5, 6, 4, 7, 3], [0, 7, 6, 2, 3, 5, 4, 1])
                set_log_to_phy_lane_mapping(5, [2, 1, 0, 3, 4, 6, 7, 5], [1, 4, 7, 5, 3, 0, 2, 6])
                set_log_to_phy_lane_mapping(6, [2, 6, 3, 1, 5, 4, 0, 7], [1, 0, 7, 4, 5, 3, 6, 2])
                set_log_to_phy_lane_mapping(7, [5, 7, 2, 3, 6, 4, 0, 1], [0, 7, 2, 6, 1, 3, 4, 5])
            elif tile==3:
                set_log_to_phy_lane_mapping(0, [7, 6, 1, 0, 5, 3, 4, 2], [1, 7, 0, 2, 3, 5, 4, 6])
                set_log_to_phy_lane_mapping(1, [4, 6, 1, 7, 0, 2, 3, 5], [4, 0, 7, 3, 1, 2, 6, 5])
                set_log_to_phy_lane_mapping(2, [1, 0, 3, 6, 5, 4, 7, 2], [3, 7, 0, 4, 5, 6, 1, 2])
                set_log_to_phy_lane_mapping(3, [6, 4, 1, 3, 0, 2, 5, 7], [2, 0, 7, 3, 4, 6, 5, 1])
                set_log_to_phy_lane_mapping(4, [6, 5, 4, 0, 7, 3, 2, 1], [2, 7, 0, 6, 5, 4, 1, 3])
                set_log_to_phy_lane_mapping(5, [6, 2, 0, 5, 4, 1, 7, 3], [6, 1, 7, 2, 4, 0, 5, 3])
                set_log_to_phy_lane_mapping(6, [3, 5, 7, 6, 0, 1, 2, 4], [0, 7, 2, 6, 1, 3, 5, 4])
                set_log_to_phy_lane_mapping(7, [0, 2, 6, 1, 4, 7, 5, 3], [0, 6, 1, 5, 2, 4, 3, 7])

