def fw_debug_info(section=2, index=2, lane=None):
    if lane == None:
        lanes = range(8)
    elif type(lane) == int:
        lanes = [lane]
    elif type(lane) == list:
        lanes = lane
    result = {}
    timeout = 0.2
    for ln in lanes:
        result[ln] = fw_debug_cmd(section, index, ln)

    return result

