def Config_BlueJay_PHY(tile=None, group=None, lane=None, mode='pam4', input_mode='ac', fw_reload=True):

    tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    
    power_up_init  ( tile, group, lane, fw_reload)
    PHY_adapt_init ( tile, group, lane, mode, input_mode)  
    #set_bg( tile, group, lane, bg_val=7, print_en=False)
    #set_bg( tile, group, lane, bg_val='table', print_en=False) # Do this in power_up_init()
    PHY_adapt_start( tile, group, lane, mode)
    PHY_adapt_wait ( tile, group, lane, timeout=1.0,print_en=False )
    
    #scan_rx_pol( tile, group, lane )
    prbs_mode_select(tile=tiles,group=groups,lane=lanes, tx_prbs_mode='prbs', rx_prbs_mode='prbs', prbs_pat='PRBS31')
    
    
    ### debug items, START
    # tx_taps(tile, group, lane, taps=[4, -15, 21, 0, 0])
    lane_reset(tile, group, lane)   
    PHY_adapt_wait ( tile, group, lane )

    ### debug items, END
    
    fw_serdes_params(tile=tiles,group=groups,lane=lanes)
    rx_monitor(rst=1,tile=tiles,group=groups,lane=lanes)
    rx_monitor_summary(rst=0,tile=tiles,group=groups,lane=lanes)
    
