def Config_BlueJay_LT_PAM4(tile=None, group=None, lane=None, mode='pam4', input_mode='ac', fw_reload=True):
                      # TGL_1=[3,1,0] <--> TGL_2=[1,0,0]
    tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    power_up_init ( tile, group, lane, fw_reload)
    LT_init       ( tile, group, lane, mode, input_mode)
    set_bg( tile, group, lane, bg_val=7)
    LT_start      ( tile, group, lane, mode)
    #set_bg(group=range(8), lane=range(8), bg_val=7)
    LT_done_wait  ( tile, group, lane )
    LT_state      ( tile, group, lane )
